# Checks that quoted strings used in evidence-d.md occur verbatim (whitespace-normalised) in the named archive file.
# usage: python3 d-verify-quotes.py   (run from docs/2610/1007/sources/)
import re, html

def load(f):
    t = open(f, encoding='utf8', errors='replace').read()
    t = html.unescape(t)
    t = t.replace('ﬃ', 'ffi').replace('ﬀ', 'ff').replace('ﬁ', 'fi').replace('ﬂ', 'fl')
    if f.endswith('.html'):
        t = re.sub(r'<script[\s\S]*?</script>|<style[\s\S]*?</style>', ' ', t)
        t = re.sub(r'<[^>]+>', ' ', t)
    return re.sub(r'\s+', ' ', t)

