bad = 0
for f, q in checks:
    t = load(f)
    qq = re.sub(r'\s+', ' ', q)
    if qq in t:
        continue
    # pdftotext hyphenation artefacts ("OpenMDW- 1.1") and JSON unicode escapes
    t2 = t.replace('- ', '-')
    q2 = qq.replace('- ', '-')
    if q2 in t2:
        continue
    bad += 1
    print('MISSING', f, '::', q[:120])
print('checked', len(checks), 'missing', bad)
